44	static inline void debug_send_line(const mbedtls_ssl_context *ssl, int level,
45	                                   const char *file, int line,
46	                                   const char *str)
47	{
48	    /*
49	     * If in a threaded environment, we need a thread identifier.
50	     * Since there is no portable way to get one, use the address of the ssl
51	     * context instead, as it shouldn't be shared between threads.
52	     */
53	#if defined(MBEDTLS_THREADING_C)
54	    char idstr[20 + DEBUG_BUF_SIZE]; /* 0x + 16 nibbles + ': ' */
55	    mbedtls_snprintf(idstr, sizeof(idstr), "%p: %s", (void *) ssl, str);
56	    ssl->conf->f_dbg(ssl->conf->p_dbg, level, file, line, idstr);
57	#else
58	    ssl->conf->f_dbg(ssl->conf->p_dbg, level, file, line, str);
59	#endif
60	}
